3	import (
4		"context"
5		"errors"
6		"net/http"
7		"net/url"
8		"strings"
9	)
10	
11	const (
12		// componentsPath lists the components of a repository.
13		componentsPath = restAPI + "/components"
14		// maxComponentPages bounds a listing: a continuation token that never ends
15		// is an error after this many calls, not an endless loop.
16		maxComponentPages = 1000
17		// manifestMarker is what the path of a Docker manifest asset holds:
18		// v2/<name>/manifests/<tag>.
19		manifestMarker = "/manifests/"
20	
21		// upCheck is what a missing admin password asks the operator to do.
22		upCheck = "run `mise run nexus-bench:up` to provision the bench"
23	)
24	
25	// component is one image tag a repository lists: the image name, the tag and,
26	// when the instance lists it, the digest of the manifest ("sha256:<hex>").
27	type component struct {
28		Name    string
29		Version string
30		Digest  string
31	}
32	
33	// adminFromStore returns a client authenticated with the stored admin password
34	// and the stored secrets. It never reads the initial password of the pod: seed,
35	// restore and reset need a bench that up already provisioned. It sends no
36	// request, so a stored password the instance refuses shows on the first call.
37	func adminFromStore(ctx context.Context, baseURL string, store SecretStore) (*client, Secrets, error) {
38		if err := ctx.Err(); err != nil {
39			return nil, Secrets{}, &transportError{Op: "read the stored admin password", Err: err}
40		}
41		sec, found, err := store.Load()
42		if err != nil {
43			return nil, Secrets{}, &BenchError{
44				Kind:  ProvisionFailed,
45				Cause: "the secrets file of the bench cannot be read",
46				Check: "check the permissions and the content of the secrets file, then " + upCheck,
47				Err:   err,
48			}
49		}
50		if !found || sec.AdminPassword == "" {
51			return nil, Secrets{}, &BenchError{
52				Kind:  ProvisionFailed,
53				Cause: "the bench has no admin password stored: it was never provisioned, or its provisioning did not finish",
54				Check: upCheck,
55				Err:   errors.New("no admin password in the secrets file"),
56			}
57		}
58		return newClient(baseURL, adminUserID, sec.AdminPassword), sec, nil
59	}
60	
61	// componentPage is one page of GET /v1/components.
62	type componentPage struct {
63		Items             []componentItem `json:"items"`
64		ContinuationToken *string         `json:"continuationToken"`
65	}
66	
67	type componentItem struct {
68		Name    string           `json:"name"`
69		Version string           `json:"version"`
70		Assets  []componentAsset `json:"assets"`
71	}
72	
73	type componentAsset struct {
74		Path     string `json:"path"`
75		Checksum struct {
76			SHA256 string `json:"sha256"`
77		} `json:"checksum"`
78	}
79	
80	// listComponents lists the components of repo, following the continuation token
81	// until the last page; a token equal to the previous one is an error. A
82	// repository the instance does not know lists as no component. An error on any
83	// page drops what the earlier pages returned.
84	//
85	// H-COMPONENTS (to settle at step 12): a Docker component is one image tag, and
86	// the sha256 checksum of its asset under v2/<name>/manifests/<tag> is the digest
87	// of the manifest.
88	func (c *client) listComponents(ctx context.Context, repo string) ([]component, error) {
89		op := "list the components of " + repo
90		var out []component
91		token := ""
92		for page := 0; page < maxComponentPages; page++ {
93			query := url.Values{"repository": {repo}}
94			if token != "" {
95				query.Set("continuationToken", token)
96			}
97			var body componentPage
98			found, err := c.get(ctx, op, componentsPath, query, &body)
99			if err != nil {
100				return nil, err
101			}
102			if !found {
103				if page == 0 {
104					return nil, nil
105				}
106				return nil, &APIError{Op: op, Status: http.StatusNotFound}
107			}
108			for _, item := range body.Items {
109				out = append(out, component{Name: item.Name, Version: item.Version, Digest: manifestDigest(item)})
110			}
111			if body.ContinuationToken == nil || *body.ContinuationToken == "" {
112				return out, nil
113			}
114			// The same token as the previous page would repeat that page for ever.
115			if *body.ContinuationToken == token {
116				return nil, &decodeError{Op: op, Err: errors.New("the continuation token repeats")}
117			}
118			token = *body.ContinuationToken
119		}
120		return nil, &decodeError{Op: op, Err: errors.New("the continuation token never ends")}
121	}
122	
123	// manifestDigest returns "sha256:<hex>" of the manifest asset of item, or "" when
124	// the instance lists none. The asset of the tag itself wins over any other
125	// manifest asset (a digest-addressed one, for instance).
126	func manifestDigest(item componentItem) string {
127		digest := ""
128		for _, a := range item.Assets {
129			if a.Checksum.SHA256 == "" || !strings.Contains(a.Path, manifestMarker) {
130				continue
131			}
132			if strings.HasSuffix(a.Path, manifestMarker+item.Version) {
133				return "sha256:" + a.Checksum.SHA256
134			}
135			if digest == "" {
136				digest = "sha256:" + a.Checksum.SHA256
137			}
138		}
139		return digest
140	}
