54	// ImageCopier copies images between registries and layouts.
55	type ImageCopier interface {
56		Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error
57		ManifestDigest(ctx context.Context, ref ImageRef, creds *Credentials) (string, error)
58	}
59	
60	const (
61		// skopeoStderrMax is how much of the stderr of skopeo is kept for the
62		// classifier; the text never reaches a message.
63		skopeoStderrMax = 64 << 10
64		// manifestMax is the largest manifest ManifestDigest reads (the limit
65		// registries apply themselves is 4 MiB).
66		manifestMax = 4 << 20
67		// skopeoKillDelay bounds the wait for skopeo's output pipes once it is
68		// killed, in case a child it started still holds them.
69		skopeoKillDelay = 2 * time.Second
70	
71		// policyAcceptAnything is the policy file of every call: skopeo refuses to
72		// run without a readable policy on a host that has none, and the bench has
73		// no signature to check. The default rule is the whole policy.
74		policyAcceptAnything = `{"default":[{"type":"insecureAcceptAnything"}]}`
75	)
76	
77	// skopeoCopier runs the skopeo found on PATH. It is, with kubectl.go and
78	// secrets.go, one of the three files of the package that start a process.
79	type skopeoCopier struct{ path string }
80	
81	// NewSkopeoCopier finds skopeo on PATH. It fails with a SkopeoMissing BenchError
82	// when skopeo is not installed.
83	func NewSkopeoCopier() (ImageCopier, error) {
84		path, err := exec.LookPath("skopeo")
85		if err != nil {
86			return nil, &BenchError{
87				Kind:  SkopeoMissing,
88				Cause: "skopeo was not found on PATH",
89				Check: "install skopeo with your package manager, then run `skopeo --version`",
90				Err:   err,
91			}
92		}
93		return &skopeoCopier{path: path}, nil
94	}
95	
96	// Copy implements ImageCopier: `skopeo copy` of src to dst. A docker reference
97	// whose host is not the loopback is refused before any process starts.
98	func (c *skopeoCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
99		if err := checkSide(src, o.SrcCreds); err != nil {
100			return err
101		}
102		if err := checkSide(dst, o.DestCreds); err != nil {
103			return err
104		}
105		w, err := newSkopeoWorkdir()
106		if err != nil {
107			return err
108		}
109		defer w.remove()
110	
111		args := []string{"--policy", w.policy, "copy"}
112		if o.PreserveDigests {
113			args = append(args, "--preserve-digests")
114		}
115		for _, side := range []struct {
116			flagPrefix string
117			ref        ImageRef
118			creds      *Credentials
119		}{{"--src-", src, o.SrcCreds}, {"--dest-", dst, o.DestCreds}} {
120			flags, err := w.sideFlags(side.flagPrefix, side.ref, side.creds)
121			if err != nil {
122				return err
123			}
124			args = append(args, flags...)
125		}
126		args = append(args, imageArg(src), imageArg(dst))
127	
128		if _, err := c.run(ctx, w, "copy", args, 0); err != nil {
129			return err
130		}
131		return nil
132	}
133	
134	// ManifestDigest implements ImageCopier: the sha256 of the raw manifest of ref,
135	// computed here from `skopeo inspect --raw`, not read from anything skopeo says
136	// about it.
137	func (c *skopeoCopier) ManifestDigest(ctx context.Context, r ImageRef, creds *Credentials) (string, error) {
138		if err := checkSide(r, creds); err != nil {
139			return "", err
140		}
141		w, err := newSkopeoWorkdir()
142		if err != nil {
143			return "", err
144		}
145		defer w.remove()
146	
147		flags, err := w.sideFlags("--", r, creds)
148		if err != nil {
149			return "", err
150		}
151		args := append([]string{"--policy", w.policy, "inspect", "--raw"}, flags...)
152		args = append(args, imageArg(r))
153	
154		manifest, err := c.run(ctx, w, "inspect", args, manifestMax)
155		if err != nil {
156			return "", err
157		}
158		if len(manifest) == 0 {
159			return "", &BenchError{
160				Kind:  SeedFailed,
161				Cause: "skopeo printed no manifest",
162				Check: "run `skopeo inspect --raw` on the same reference by hand",
163			}
164		}
165		sum := sha256.Sum256(manifest)
166		return "sha256:" + hex.EncodeToString(sum[:]), nil
167	}
168	
169	// run starts skopeo with args in the environment of w and returns its stdout
170	// (at most stdoutMax bytes; with 0 the stdout is dropped). Nothing skopeo prints
171	// reaches the error: the stderr only picks its kind.
172	func (c *skopeoCopier) run(ctx context.Context, w *skopeoWorkdir, op string, args []string, stdoutMax int) ([]byte, error) {
173		cmd := exec.CommandContext(ctx, c.path, args...) //nolint:gosec // the binary is the skopeo found on PATH and the references were checked by checkSide
174		cmd.Env = skopeoEnvironment(w.registriesConf)
175		cmd.WaitDelay = skopeoKillDelay
176		stdout, stderr := newCapWriter(stdoutMax), newCapWriter(skopeoStderrMax)
177		cmd.Stdout, cmd.Stderr = stdout, stderr
178	
179		runErr := cmd.Run()
180		if runErr == nil {
181			if stdoutMax > 0 && stdout.over {
182				return nil, &BenchError{
183					Kind:  SeedFailed,
184					Cause: "the manifest is larger than the 4 MiB registries accept",
185					Check: "run `skopeo inspect --raw` on the same reference by hand",
186				}
187			}
188			return stdout.buf.Bytes(), nil
189		}
190		if ctxErr := ctx.Err(); ctxErr != nil {
191			kind := Unclassified
192			if errors.Is(ctxErr, context.DeadlineExceeded) {
193				kind = Deadline
194			}
195			return nil, &BenchError{
196				Kind:  kind,
197				Cause: fmt.Sprintf("skopeo %s was interrupted", op),
198				Check: "run the command again",
199				Err:   ctxErr,
200			}
201		}
202		return nil, skopeoFailure(op, classifySkopeo(stderr.buf.String()), runErr)
203	}
204	
205	// skopeoFailure builds the error of a skopeo that exited with a failure.
206	func skopeoFailure(op string, kind ErrKind, runErr error) *BenchError {
207		be := &BenchError{Kind: kind, Err: runErr}
208		switch kind {
209		case RegistryUnreachable:
210			be.Cause = fmt.Sprintf("skopeo %s could not reach a registry", op)
211			be.Check = "check that the port-forward is running and the registry answers on its port"
212		case RegistryRefused:
213			be.Cause = fmt.Sprintf("a registry refused the skopeo %s", op)
214			be.Check = "check the bench credentials in the secrets file and the privileges of the account"
215		case SeedFailed:
216			be.Cause = fmt.Sprintf("skopeo %s did not find the image", op)
217			be.Check = "check that the image and its tag exist in the source registry"
218		default:
219			be.Cause = fmt.Sprintf("skopeo %s failed", op)
220			be.Check = "run the same skopeo command by hand to see what it says"
221		}
222		return be
223	}
224	
225	// imageArg is how skopeo is given an ImageRef: docker://<location>, or
226	// <transport>:<location>.
227	func imageArg(r ImageRef) string {
228		if r.Transport == "docker" {
229			return "docker://" + r.Location
230		}
231		return r.Transport + ":" + r.Location
232	}
233	
234	// checkSide refuses, before any process starts, a reference skopeo must not be
235	// given: an unknown transport, credentials for a side that is not a registry,
236	// and a docker reference whose host is not the loopback (TLS verification is
237	// switched off for every docker reference, so the host is the only protection).
238	func checkSide(r ImageRef, creds *Credentials) error {
239		switch r.Transport {
240		case "oci", "dir":
241			if creds != nil {
242				return &BenchError{
243					Kind:  Unclassified,
244					Cause: "credentials were given for an image that is not in a registry",
245					Check: "give credentials only for a docker reference",
246				}
247			}
248			return nil
249		case "docker":
250			host, name, hasName := strings.Cut(r.Location, "/")
251			if !hasName || name == "" || !loopbackRegistry(host) {
252				return &BenchError{
253					Kind:  Unclassified,
254					Cause: "the bench only talks to a registry on the loopback, with a repository name: TLS verification is off for it",
255					Check: "reach the registry through the port-forward and give 127.0.0.1:<port>/<name>[:<tag>]",
256				}
257			}
258			return nil
259		}
260		return &BenchError{
261			Kind:  Unclassified,
262			Cause: "the image transport is not one of oci, dir and docker",
263			Check: "give a reference whose transport is oci, dir or docker",
264		}
265	}
266	
267	// registryHost is the "<host[:port]>" part of a docker location. checkSide has
268	// already required a "/" and a repository name after it: without them skopeo
269	// reads "localhost:5000" as an image of docker.io.
270	func registryHost(location string) string {
271		host, _, _ := strings.Cut(location, "/")
272		return host
273	}
274	
275	// loopbackRegistry tells whether hostPort ("127.0.0.1:5000", "[::1]:5000") is
276	// one of the two loopback literals and nothing else ("localhost" is not: it
277	// resolves through the host's configuration). It parses the host and the
278	// port instead of testing a prefix, so "127.0.0.1@evil.com",
279	// "127.0.0.1.evil.com" and "127.0.0.1:5000@evil.com" are not the loopback.
280	func loopbackRegistry(hostPort string) bool {
281		host := hostPort
282		if h, p, err := net.SplitHostPort(hostPort); err == nil {
283			if n, err := strconv.Atoi(p); err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != p {
284				return false
285			}
286			host = h
287			if strings.HasPrefix(hostPort, "[") {
288				return host == "::1"
289			}
290		} else if strings.HasPrefix(hostPort, "[") && strings.HasSuffix(hostPort, "]") {
291			return hostPort == "[::1]"
292		}
293		return host == "127.0.0.1"
294	}
295	
296	// skopeoWorkdir is the temporary folder of one skopeo call: the policy, the
297	// empty registries.conf and the authentication files. The folder is 0700, the
298	// files are 0600, and remove deletes all of it whatever happened.
299	type skopeoWorkdir struct {
300		dir            string
301		policy         string
302		registriesConf string
303	}
304	
305	// newSkopeoWorkdir creates the folder with the policy and the empty
306	// registries.conf already in it.
307	func newSkopeoWorkdir() (*skopeoWorkdir, error) {
308		dir, err := os.MkdirTemp("", "devdesk-skopeo-") // 0700
309		if err != nil {
310			return nil, &BenchError{
311				Kind:  Unclassified,
312				Cause: "the temporary folder for skopeo could not be created",
313				Check: "check that the temporary folder is writable and not full",
314				Err:   err,
315			}
316		}
317		w := &skopeoWorkdir{dir: dir, policy: filepath.Join(dir, "policy.json"), registriesConf: filepath.Join(dir, "registries.conf")}
318		for path, content := range map[string]string{w.policy: policyAcceptAnything, w.registriesConf: ""} {
319			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
320				w.remove()
321				return nil, workdirError(err)
322			}
323		}
324		return w, nil
325	}
326	
327	// remove deletes the folder and everything in it. It is called by defer, so it
328	// runs after a failure and a cancellation as well.
329	func (w *skopeoWorkdir) remove() { _ = os.RemoveAll(w.dir) }
330	
331	func workdirError(err error) *BenchError {
332		return &BenchError{
333			Kind:  Unclassified,
334			Cause: "a temporary file for skopeo could not be written",
335			Check: "check that the temporary folder is writable and not full",
336			Err:   err,
337		}
338	}
339	
340	// sideFlags returns the flags of one side of a call, for a flag prefix of
341	// "--src-", "--dest-" or "--": TLS verification off for a docker reference only,
342	// and either "<prefix>no-creds" or "<prefix>authfile <file>" holding the
343	// credentials. The credentials go to a file because an argument is visible to
344	// every account through /proc.
345	func (w *skopeoWorkdir) sideFlags(prefix string, r ImageRef, creds *Credentials) ([]string, error) {
346		var flags []string
347		if r.Transport == "docker" {
348			flags = append(flags, prefix+"tls-verify=false")
349		}
350		if creds == nil {
351			return append(flags, prefix+"no-creds"), nil
352		}
353		// One file per side, so the credentials of a side are never offered to the other.
354		name := "auth.json"
355		if prefix != "--" {
356			name = strings.Trim(prefix, "-") + "-auth.json"
357		}
358		path := filepath.Join(w.dir, name)
359		content, err := json.Marshal(map[string]any{"auths": map[string]any{
360			registryHost(r.Location): map[string]string{"auth": base64.StdEncoding.EncodeToString([]byte(creds.User + ":" + creds.Password))},
361		}})
362		if err != nil {
363			return nil, workdirError(err)
364		}
365		if err := os.WriteFile(path, content, 0o600); err != nil {
366			return nil, workdirError(err)
367		}
368		return append(flags, prefix+"authfile", path), nil
369	}
370	
371	// skopeoEnvironment is the environment of the skopeo process: the caller's,
372	// without the proxy variables (which would send the bench traffic elsewhere),
373	// REGISTRY_AUTH_FILE (which would name a login of the host) and every
374	// CONTAINERS_* variable (which would change the configuration, the policy or the
375	// certificates), and with CONTAINERS_REGISTRIES_CONF pointing at registriesConf,
376	// an empty file, so no mirror or redirect of the host applies. Names are compared
377	// in upper case because Windows environment names are case-insensitive.
378	func skopeoEnvironment(registriesConf string) []string {
379		var env []string
380		for _, kv := range os.Environ() {
381			name, _, _ := strings.Cut(kv, "=")
382			upper := strings.ToUpper(name)
383			switch upper {
384			case "HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "REGISTRY_AUTH_FILE":
385				continue
386			}
387			if strings.HasPrefix(upper, "CONTAINERS_") {
388				continue
389			}
390			env = append(env, kv)
391		}
392		return append(env, "CONTAINERS_REGISTRIES_CONF="+registriesConf)
393	}
