// readPod describes the Nexus pod in one line: its phase, name, readiness and restarts.
func readPod(s *session, r nexusbench.Runner) string {
	stdout, _, err := r.Run(s.ctx, nil, "get", "pods", "-n", s.p.Namespace, "-l", nexusPodSelector, "-o", "json", "--request-timeout=10s")
	if err != nil {
		return "unknown (kubectl get pods failed)"
	}
	var list podList
	if err := json.Unmarshal(stdout, &list); err != nil {
		return "unknown (kubectl get pods returned something unreadable)"
	}
	if len(list.Items) == 0 {
		return "not found"
	}
	item := list.Items[0]
	phase := strings.ToLower(item.Status.Phase)
	if item.Metadata.DeletionTimestamp != "" {
		phase = "terminating"
	}
	if phase == "" {
		phase = "unknown"
	}
	ready, restarts := 0, 0
	for _, c := range item.Status.ContainerStatuses {
		if c.Ready {
			ready++
		}
		restarts += c.RestartCount
	}
	line := fmt.Sprintf("%s (%s, %d/%d ready, %d restarts", phase, item.Metadata.Name, ready, len(item.Status.ContainerStatuses), restarts)
	if len(list.Items) > 1 {
		line += fmt.Sprintf(", %d more pods", len(list.Items)-1)
	}
	return line + ")"
}

// describeDescriptor compares the versioned descriptor with the parameters of
// this run and says where they differ.
func (s *session) describeDescriptor() string {
	path := s.descriptorPath()
	d, err := nexusbench.LoadDescriptor(path)
	switch {
	case errors.Is(err, nexusbench.ErrNoDescriptor):
		return "not found (" + path + ")"
	case err != nil:
		return "unreadable (" + err.Error() + ")"
	}
	diffs := descriptorDiffs(d, s.p)
	if len(diffs) == 0 {
		return "matches (" + path + ")"
	}
	return "differs from the current parameters (" + path + ")\n  " + strings.Join(diffs, "\n  ")
}

// descriptorDiffs lists the fields of the descriptor that the parameters of
// this run would write differently. The hosts and the versions are left out:
// they come from the cluster, not from the parameters. So is the dataset, which
// the parameters know nothing of.
func descriptorDiffs(d nexusbench.Descriptor, p nexusbench.Params) []string {
	want := nexusbench.BuildDescriptor(p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, nexusbench.SeedResult{})
	fields := []struct{ name, got, want string }{
		{"context", d.KubeContext, want.KubeContext},
		{"namespace", d.Namespace, want.Namespace},
		{"image", d.Image, want.Image},
		{"http nodePort", strconv.Itoa(d.REST.NodePort), strconv.Itoa(want.REST.NodePort)},
		{"docker nodePort", dockerPort(d), dockerPort(want)},
		{"upstream URL", upstreamURL(d), upstreamURL(want)},
		{"upstream image", d.Upstream.Image, want.Upstream.Image},
		{"anonymous access", anonymous(d), anonymous(want)},
	}
	var diffs []string
	for _, f := range fields {
		if f.got != f.want {
			diffs = append(diffs, fmt.Sprintf("%s: descriptor %s, current %s", f.name, f.got, f.want))
		}
	}
	return diffs
}

func dockerPort(d nexusbench.Descriptor) string {
	if len(d.DockerConnectors) == 0 {
		return "none"
	}
	return strconv.Itoa(d.DockerConnectors[0].NodePort)
}

func upstreamURL(d nexusbench.Descriptor) string {
	for _, r := range d.Repositories {
		if r.Type == "proxy" {
			return r.RemoteURL
		}
	}
	return "none"
}

func anonymous(d nexusbench.Descriptor) string {
	for _, a := range d.Accounts {
		if a.UserID == "anonymous" && a.Enabled != nil {
			return strconv.FormatBool(*a.Enabled)
		}
	}
	return "unset"
}
package nexusbench

// Location is where an image of the data set lives: "docker-hosted" or "upstream".
type Location string

// The two places the data set puts an image.
const (
	// LocationHosted is the docker-hosted repository of the bench Nexus.
	LocationHosted Location = "docker-hosted"
	// LocationUpstream is the registry the docker-proxy repository mirrors.
	LocationUpstream Location = "upstream"
)

// DatasetImage is one image of the fixed data set.
type DatasetImage struct {
	Name, Tag   string
	Location    Location
	PullThrough bool   // pulled once through docker-proxy by Seed
	Digest      string // manifest digest, sha256:...
}

// datasetTable is the fixed data set of DEVDESK-505 (D-I), in order. The digests
// are not written here: Dataset computes them from the generator, so a change of
// the generator can never leave a stale value behind.
var datasetTable = []DatasetImage{
	{Name: "api", Tag: "1.0.0", Location: LocationHosted},
	{Name: "api", Tag: "1.1.0", Location: LocationHosted},
	{Name: "team/api", Tag: "1.0.0", Location: LocationHosted},
	{Name: "tools/cli", Tag: "0.1.0", Location: LocationHosted},
	// The same name and tag in both places, with different contents: a read
	// through the group says which member answered.
	{Name: "shared/base", Tag: "1.0", Location: LocationHosted},
	{Name: "shared/base", Tag: "1.0", Location: LocationUpstream},
	{Name: "mirror/cached", Tag: "1.0", Location: LocationUpstream, PullThrough: true},
	{Name: "mirror/uncached", Tag: "1.0", Location: LocationUpstream},
}

// Dataset returns the fixed data set, in order, with the manifest digest of every
// image filled from the layout generator. The slice is a copy.
func Dataset() []DatasetImage {
	images := make([]DatasetImage, len(datasetTable))
	for i, img := range datasetTable {
		img.Digest = imageDigest(img)
		images[i] = img
	}
	return images
}
package nexusbench

import (
	"context"
	"time"
)

// Clock is the time the waits of the bench read and spend. Tests swap it for a
// fake that never waits, so no test sleeps for real.
type Clock interface {
	// Now returns the current time.
	Now() time.Time
	// Sleep waits for d, or until ctx is done. It returns ctx.Err() when ctx is
	// done, before sleeping if it already was, and nil after the whole wait. A
	// duration of zero or less returns at once (after the ctx check).
	Sleep(ctx context.Context, d time.Duration) error
}

// realClock is the Clock of the command: the wall clock.
type realClock struct{}

// NewClock returns the real clock.
func NewClock() Clock { return realClock{} }

// Now implements Clock.
func (realClock) Now() time.Time { return time.Now() }

// Sleep implements Clock.
func (realClock) Sleep(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if d <= 0 {
		return nil
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

package nexusbench

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
